"OLAYLAR_ARKEOLOJI_D2_HINT_GUNEYDOGU:-2999-01-01:0":{"b": ["Neolitik južne Indije (tradicija pepelnih humaka, Dekan): južna Indija: najstariji sloj naseljavanja u Kodekalu (ugljen)", "34f260d2"], "d": ["Stočarski neolitik na jugu Dekana, prepoznatljiv po humcima pepela od goveđeg gnoja (ashmound); Kodekal, sloj 4 (prije pepelnog humka) 'rani 3. milenij'.", "92cd6e14"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0199-01-01:0":{"b": ["Tepe Yahya: završava se Period I (posljednja faza naseljavanja)", "879e6b45"], "d": ["Tell s dugim stratigrafskim nizom u jugoistočnom Iranu; Period VII (neolitik s keramikom, 5500-4500), Period IVC2 (3100-2800) kompleks velike zgrade s protoelamskim pločicama i materijalom tipa Suza III; IVB 2400-2000; IVA 1800-1400; III 800-500; II 500-275; I 200 BCE-300 CE.", "a059993d"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0329-01-01:0":{"b": ["Ahemenidsko carstvo / Persida Kira II: Ahemenidska država prestaje (Darije III, 330)", "798918ed"], "d": ["559: početak vladavine Kira II (granica vladavine koju daje članak o Pasargadu); 550: zbacivanje medijskog kralja Astijaga i ujedinjenje Irana (Schmitt); 330: kraj Darija III.", "5a8e254a"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0538-01-01:0":{"b": ["Elam (Stari Elam - Novi Elam): završava se razdoblje Novog Elama", "64fe1dfe"], "d": ["Dinastija Avan (c. 2400-2100. p. n. e.), Šimaški, Epartidi/sukkalmah (savremenici Starog Babilona); Srednji Elam (Untaš-Napiriša c. 1340-1300, Čoga Zanbil); Novi Elam (1100-539). Ime Elam prvi put se u izvoru javlja u tekstu kralja Kiša Enmebaragesija (c. 2650. p. n. e.); Novi Elam II c. 770-646 (sukob s Asirijom).", "e35bcb7b"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0558-01-01:0":{"b": ["Ahemenidsko carstvo / Persida Kira II: Kir II stupa na perzijsko prijestolje (559)", "c0d9c31b"], "d": ["559: početak vladavine Kira II (granica vladavine koju daje članak o Pasargadu); 550: zbacivanje medijskog kralja Astijaga i ujedinjenje Irana (Schmitt); 330: kraj Darija III.", "5a8e254a"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-0699-01-01:0":{"b": ["Medijska država (sa središtem u Hegmatani): Medijska država: počinje doba Dejoka (Herodotova tradicija)", "26e483d1"], "d": ["Političko ujedinjenje/država Međana: Herodotova tradicija počinje ga s Dejokom (c. 700-647); alternativna hronologija Grantovskog, zasnovana na asirskim izvorima, stavlja medijski ustanak oko c. 672, a Dejoka oko c. 672/671. Posljednjeg medijskog kralja Astijaga 550. p. n. e. zbacuje Kir (medijsko-perzijski rat 553-550).", "ce4a8a35"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-2169-01-01:0":{"b": ["Tepe Hissar: završava se faza IIIC", "be19ff7c"], "d": ["Tell iz halkolitika i ranog bronzanog doba blizu Damgana (Hissar I-III); prema kalibriranom 14C IC/IIA ~3980-3865. p. n. e., IIB 3365-3030, IIIB 2400-2170, IIIC 2170-1900.", "505d235c"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-2399-01-01:0":{"b": ["Elam (Stari Elam - Novi Elam): počinje dinastija Avan (prva elamska dinastija)", "b8a35586"], "d": ["Dinastija Avan (c. 2400-2100. p. n. e.), Šimaški, Epartidi/sukkalmah (savremenici Starog Babilona); Srednji Elam (Untaš-Napiriša c. 1340-1300, Čoga Zanbil); Novi Elam (1100-539). Ime Elam prvi put se u izvoru javlja u tekstu kralja Kiša Enmebaragesija (c. 2650. p. n. e.); Novi Elam II c. 770-646 (sukob s Asirijom).", "e35bcb7b"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-3199-01-01:0":{"b": ["Protoelamski sistem pisma (Suza): pojavljuje se protoelamsko pismo", "a88d66b7"], "d": ["U Suzi nedešifrirani protoelamski sistem pisma, savremen s Urukom III; širi se na osam mjesta na iranskoj visoravni. '~3100. p. n. e.' iz brifa nije nađeno ni u jednom izvoru; izvori daju početak 3200.", "e4504100"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-3921-01-01:0":{"b": ["Tepe Hissar: počinje faza IC/IIA (najstarija faza datirana 14C)", "8d917577"], "d": ["Tell iz halkolitika i ranog bronzanog doba blizu Damgana (Hissar I-III); prema kalibriranom 14C IC/IIA ~3980-3865. p. n. e., IIB 3365-3030, IIIB 2400-2170, IIIC 2170-1900.", "505d235c"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-3999-01-01:0":{"b": ["Suza: osniva se grad (približno, Iranica)", "63ff02c7"], "d": ["Središte Suzijane; Iranica daje osnivanje ca. 4000. p. n. e. Kasna Suza II (c. 3500-3100. p. n. e.) dijeli istu materijalnu kulturu s Urukom; zatim dolaze protoelamsko razdoblje, akadsko osvajanje (c. 2300. p. n. e.), uključivanje u Ur III (Suza VB) i elamska kraljevstva.", "39f0c741"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-4299-01-01:0":{"b": ["Anau IA i horizont Meana (Kopet Dag, rani halkolitik): faza Anau Ia (najniži slojevi)", "14def83f"], "d": ["Postdžejtunski halkolitik u podnožju Kopet Daga; na Monjukli Depeu je prije Anau IA definiran zaseban 'horizont Meana' (c. 4650-4340. p. n. e. cal).", "5d2520ea"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-5499-01-01:0":{"b": ["Tepe Yahya: počinje Period VII (Iranica; privremena tabela)", "9396a756"], "d": ["Tell s dugim stratigrafskim nizom u jugoistočnom Iranu; Period VII (neolitik s keramikom, 5500-4500), Period IVC2 (3100-2800) kompleks velike zgrade s protoelamskim pločicama i materijalom tipa Suza III; IVB 2400-2000; IVA 1800-1400; III 800-500; II 500-275; I 200 BCE-300 CE.", "a059993d"]},
"OLAYLAR_ARKEOLOJI_D2_IRAN_ORTA_ASYA:-5919-01-01:0":{"b": ["Gadachrili Gora: Šulaveri-Šomu: prvi slojevi tella", "3c414a94"], "d": ["Tell kulture Šulaveri-Šomu u Kvemo Kartliju (Marneuli); dvije faze naseljavanja, kružne jedinice i skladišne građevine.", "115962d7"]},
